import{_ as t,o as a,c as i,aa as o}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/media/en/diary/slider5_maly.jpg",m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction","wiki":"en:diary:introduction"},"headers":[],"relativePath":"en/diary/introduction.md","filePath":"en/diary/introduction.md","lastUpdated":1794388980000}'),r={name:"en/diary/introduction.md"};function s(c,e,d,l,u,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Buildary.online is an application designed to maintain a construction project diary in electronic form. Diaries are kept to provide a complete picture of the project, covering both the normal work processes and anything unusual that might have occurred on the project. The diary is used to document work progress, site conditions, labour and equipment usage, and the contractor’s ability (or inability) to perform his/her work., and can provide valuable information necessary to accurately reconstruct the events of the project in preparation of a claim. The diaries will become an important part of the project records if the project is subjected to audit, investigation, or litigation.</p><p>Buildary.online as a cloud application grants access to any authorized person anytime and anywhere provided Internet connection is available. Buildary.online application is run in the Microsoft Azure cloud. Data is protected against unauthorized access, loss or abuse. Its data are guaranteed not to leave the territory of the European Union.</p><img src="'+n+'" alt="Web site www.buildary.online" width="400" data-no-zoom loading="lazy"><p>We recommend that you launch the application from the site <a href="https://buildary.online" target="_blank" rel="noreferrer">www.buildary.online</a> where the latest application-related news and the best practice are published.</p><h2 id="legislation-compliance" tabindex="-1">Legislation compliance <a class="header-anchor" href="#legislation-compliance" aria-label="Permalink to &quot;Legislation compliance&quot;">​</a></h2><p>Writing a construction diary is a legal obligation in some countries. In others, it is considered optional but very useful. Our solution meets the most demanding legislative requirements. Buildary supports certificate signature which is necessary for construction diary digital form in some countries. PDF report signed with a qualified certificate signature is a legally binding document which can stand as evidence during any litigation.</p><h2 id="experiences-and-ideas-for-further-development" tabindex="-1">Experiences and ideas for further development <a class="header-anchor" href="#experiences-and-ideas-for-further-development" aria-label="Permalink to &quot;Experiences and ideas for further development&quot;">​</a></h2><p>Our company has 25 years of experience in construction industry software. That does not mean we know everything and we have nothing to learn. Exactly opposite. We welcome and appreciate any feedback from our users and their suggestions for further development. We promise to take all the remarks seriously and analyse them thoroughly. We consider close cooperation with our users to be a key success factor.</p><p>Do not hesitate to contact us, please.</p>',10)])])}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
